import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Card, Button, DatePicker, Alert, Space, Title, Text, Tag } from '../components/BasicUI';
import './Home.css';

const Home = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [analyzing, setAnalyzing] = useState({});
  const [statusFilter, setStatusFilter] = useState('all');
  const [filteredGames, setFilteredGames] = useState([]);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [lastUpdate, setLastUpdate] = useState(null);
  const intervalRef = useRef(null);

  const fetchGames = async (date) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(`/api/games/today?date=${date}`);
      setGames(response.data.data || []);
    } catch (error) {
      setError(error.response?.data?.error || 'Error al cargar los partidos');
    } finally {
      setLoading(false);
    }
  };

  // Filtrar partidos por estado
  const filterGamesByStatus = (games, status) => {
    if (status === 'all') return games;
    return games.filter(game => game.status === status);
  };

  // Aplicar filtros cuando cambien los juegos o el filtro
  useEffect(() => {
    const filtered = filterGamesByStatus(games, statusFilter);
    setFilteredGames(filtered);
  }, [games, statusFilter]);

  const analyzeGame = async (mlbId) => {
    setAnalyzing(prev => ({ ...prev, [mlbId]: true }));
    try {
      await axios.post(`/api/games/analyze/${mlbId}`);
      // Recargar partidos para mostrar el estado actualizado
      await fetchGames(selectedDate);
    } catch (error) {
      setError(error.response?.data?.error || 'Error al analizar el partido');
    } finally {
      setAnalyzing(prev => ({ ...prev, [mlbId]: false }));
    }
  };

  const handleDateChange = (e) => {
    const date = e.target.value;
    setSelectedDate(date);
    fetchGames(date);
  };

  useEffect(() => {
    fetchGames(selectedDate);
  }, []);

  const formatTime = (time) => {
    if (!time) return 'TBD';
    try {
      return new Date(`2000-01-01T${time}`).toLocaleTimeString('es-ES', { 
        hour: '2-digit', 
        minute: '2-digit' 
      });
    } catch (error) {
      return time;
    }
  };

  const getTeamAbbreviation = (name) => {
    const words = name.split(' ');
    if (words.length === 1) return name.substring(0, 2).toUpperCase();
    return words.map(word => word[0]).join('').toUpperCase();
  };

  const getStatusLabel = (status) => {
    const statusLabels = {
      'scheduled': 'Programado',
      'in progress': 'En Progreso',
      'final': 'Finalizado',
      'warmup': 'Calentamiento',
      'pre-game': 'Pre-Juego',
      'live': 'En Vivo',
      'delayed': 'Retrasado',
      'postponed': 'Aplazado',
      'cancelled': 'Cancelado',
      'suspended': 'Suspendido',
      '': 'Sin Estado'
    };
    return statusLabels[status] || status || 'Sin Estado';
  };

  const getStatusColor = (status) => {
    const statusColors = {
      'scheduled': 'blue',
      'in progress': 'orange',
      'final': 'green',
      'warmup': 'yellow',
      'pre-game': 'blue',
      'live': 'orange',
      'delayed': 'yellow',
      'postponed': 'yellow',
      'cancelled': 'red',
      'suspended': 'purple',
      '': 'gray'
    };
    return statusColors[status] || 'gray';
  };

  return (
    <div className="home-page">
      <Title level={1}>Partidos del Día</Title>

      <Space direction="vertical" size="large">
        {/* Filtros */}
        <Card title="Filtros">
          <Space wrap>
            <div>
              <Text>Fecha:</Text>
              <input
                type="date"
                value={selectedDate}
                onChange={handleDateChange}
                className="basic-date-picker"
              />
            </div>
            <div>
              <Text>Estado:</Text>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="basic-input"
              >
                <option value="all">Todos los Estados</option>
                <option value="final">Finalizados</option>
                <option value="in progress">En Progreso</option>
                <option value="">Sin Estado</option>
              </select>
            </div>
          </Space>
        </Card>

        {/* Mensajes de error */}
        {error && (
          <Alert type="error" message="Error" description={error} />
        )}

        {/* Información sobre estados */}
        <Card title="Información de Estados">
          <Text>
            <strong>Estados disponibles:</strong> Finalizados, En Progreso, Sin Estado
          </Text>
          <Text style={{ marginTop: '8px', fontSize: '12px', color: '#888' }}>
            Nota: Algunos partidos pueden aparecer como "Sin Estado" debido a actualizaciones en tiempo real de la API de MLB.
          </Text>
        </Card>

        {/* Lista de partidos */}
        <div className="games-container">
          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
              <Text>Cargando partidos...</Text>
            </div>
          ) : filteredGames.length > 0 ? (
            filteredGames.map((game) => (
              <div key={game.id} className="game-card">
                {/* Header del partido */}
                <div className="game-header">
                  <div className="game-teams">
                    {/* Equipo visitante */}
                    <div className="team-info">
                      <div className="team-logo">
                        {getTeamAbbreviation(game.away_team_name)}
                      </div>
                      <div className="team-name">{game.away_team_name}</div>
                      <div className="team-record">Record: 0-0</div>
                    </div>

                    {/* VS */}
                    <div className="vs-indicator">VS</div>

                    {/* Equipo local */}
                    <div className="team-info">
                      <div className="team-logo">
                        {getTeamAbbreviation(game.home_team_name)}
                      </div>
                      <div className="team-name">{game.home_team_name}</div>
                      <div className="team-record">Record: 0-0</div>
                    </div>
                  </div>

                  {/* Hora del partido */}
                  <div className="game-time">
                    {formatTime(game.game_time)}
                  </div>
                </div>

                {/* Estado del partido */}
                <div className="game-status">
                  <Tag color={getStatusColor(game.status)}>
                    {getStatusLabel(game.status)}
                  </Tag>
                </div>

                {/* Ubicación */}
                <div className="game-location">
                  Estadio, Ciudad, País
                </div>

                {/* Información de pitchers (simulada) */}
                <div className="game-pitchers">
                  <div className="pitcher-info">
                    <div className="pitcher-name">Pitcher Visitante</div>
                    <div className="pitcher-stats">LZ #XX | 0-0, 0.00 ERA</div>
                  </div>
                  <div className="pitcher-info">
                    <div className="pitcher-name">Pitcher Local</div>
                    <div className="pitcher-stats">LD #XX | 0-0, 0.00 ERA</div>
                  </div>
                </div>

                {/* Acciones */}
                <div className="game-actions">
                  <Button
                    type={game.status === 'analyzed' ? 'success' : 'primary'}
                    onClick={() => analyzeGame(game.mlb_id)}
                    loading={analyzing[game.mlb_id]}
                    disabled={game.status === 'analyzed'}
                    className={`action-button ${game.status === 'analyzed' ? 'success' : 'primary'}`}
                  >
                    {game.status === 'analyzed' ? '✓ Analizado' : 'Analizar'}
                  </Button>

                  <Button
                    type="secondary"
                    className="action-button secondary"
                  >
                    Vista Previa
                  </Button>

                  <Button
                    type="secondary"
                    className="action-button secondary"
                  >
                    Detalles
                  </Button>
                </div>

                {/* Estado del análisis */}
                {game.status === 'analyzed' && (
                  <div className="analysis-status">
                    <div className="status-badge analyzed">
                      ✓ Análisis Completado
                    </div>
                  </div>
                )}
              </div>
            ))
          ) : (
            <Card title="No hay partidos">
              <Text>
                {statusFilter === 'all' 
                  ? 'No se encontraron partidos para la fecha seleccionada.'
                  : `No se encontraron partidos con estado "${getStatusLabel(statusFilter)}" para la fecha seleccionada.`
                }
              </Text>
            </Card>
          )}
        </div>
      </Space>
    </div>
  );
};

export default Home;
